		/** 
		 * Tests creating a new Claim.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Claim");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Claim" );

			try {            
				Claim entity = ClaimService.getClaimInstance().createClaim( generateNewEntity() );
				thePrimaryKey = entity.getClaimId();
				LOGGER.info( "-- Successfully created a Claim with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Claim. 
		 */
		public Claim testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Claim" );

			Claim entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Claim with primary key" );
			msg.append( thePrimaryKey );
			
			ClaimFetchOneSummary fetchOneSummary = new ClaimFetchOneSummary( thePrimaryKey );

			try {
				entity = ClaimService.getClaimInstance().getClaim( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Claim " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Claim.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Claim." );

			StringBuilder msg = new StringBuilder( "Failed to update a Claim : " );        
			Claim entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Claim." );

				// for use later on...
				thePrimaryKey = entity.getClaimId();

				ClaimService proxy = ClaimService.getClaimInstance();            
				proxy.updateClaim( entity );   

				LOGGER.info( "-- Successfully saved Claim - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Claim.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Claim." );

			try{
			    Claim entity = testRead(); 
				ClaimService.getClaimInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Claim with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Claim with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Claims.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Claims:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Claim : " );        
			List<Claim> collection  = null;

			try {
				// call the static get method on the ClaimService
				collection = ClaimService.getClaimInstance().getAllClaim();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Claim entity = null;            
					Iterator<Claim> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getClaimId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

